{"files":[{"path":"index.html","old_sha256":"76cda301f0d1bf073c55adb7fc2ed12e84814a4c889266cd8a8bfce658ba446c","content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Voxel Sandbox</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<header>
  <h1>Voxel Sandbox</h1>
  <div class="hud">
    <div id="world">world 8x8</div>
    <div id="position">1,1,1</div>
    <div id="facing">east</div>
    <div id="selected">none</div>
    <div id="status">ready</div>
  </div>
  <div class="controls">
    <button id="turn-left">Turn Left</button>
    <button id="turn-right">Turn Right</button>
    <button id="break">Break</button>
    <select id="hotbar"><option value="dirt" selected>dirt</option><option value="stone">stone</option><option value="glass">glass</option></select>
    <button id="place">Place</button>
    <button id="save">Save</button>
    <button id="load">Load</button>
  </div>
</header>
<main>
  <div id="scene"></div>
</main>
<script src="world.js"></script>
<script src="rules.js"></script>
<script src="storage.js"></script>
<script src="app.js"></script>
</body>
</html>
"},{"path":"storage.js","old_sha256":"152df16cc119c47986c9db594ae03f76bbfaa7835fd9b49ddc12db023f72756d","content":"const Storage = {
  key: 'voxel-save',
  facingOrder: ['east', 'south', 'west', 'north'],
  save(World) {
    const blocks = [];
    for (const k in World.blocks) {
      const b = World.blocks[k];
      if (b.material === 'dirt' || b.material === 'stone' || b.material === 'glass') blocks.push([b.x, b.y, b.z, b.material]);
    }
    const facing = this.facingOrder.indexOf(World.player.facing);
    const data = { version: 2, blocks, player: [World.player.x, 1, World.player.z], facing };
    try { localStorage.setItem(this.key, JSON.stringify(data)); return true; }
    catch (e) { return false; }
  },
  load(World) {
    let raw;
    try { raw = localStorage.getItem(this.key); } catch (e) { return null; }
    if (!raw) return null;
    let d;
    try { d = JSON.parse(raw); } catch (e) { return null; }
    if (!d || (d.version !== 1 && d.version !== 2)) return null;
    if (!Array.isArray(d.blocks) || !Array.isArray(d.player) || d.player.length !== 3) return null;
    if (typeof d.facing !== 'number' || d.facing < 0 || d.facing > 3 || d.facing % 1 !== 0) return null;
    const seen = {};
    for (const b of d.blocks) {
      if (!Array.isArray(b) || b.length !== 4) return null;
      const [x, y, z, m] = b;
      if (![x, y, z].every(n => Number.isInteger(n))) return null;
      if (!World.inBounds(x, y, z)) return null;
      if (d.version === 1) { if (m !== 'dirt' && m !== 'stone') return null; }
      else { if (m !== 'dirt' && m !== 'stone' && m !== 'glass') return null; }
      const k = x + ',' + y + ',' + z;
      if (seen[k]) return null;
      seen[k] = true;
    }
    const [px, py, pz] = d.player;
    if (![px, py, pz].every(n => Number.isInteger(n))) return null;
    if (py !== 1) return null;
    if (!World.inBounds(px, py, pz)) return null;
    if (seen[px + ',' + py + ',' + pz]) return null;
    if (seen[px + ',' + (py + 1) + ',' + pz]) return null;
    return { blocks: d.blocks, player: [px, 1, pz], facing: this.facingOrder[d.facing] };
  }
};
"},{"path":"style.css","old_sha256":"f2e7998a77d3a462b15d5e51e5fc825f1ab41970b3868465d94467c01888c58c","content":"*{box-sizing:border-box}
body{margin:0;font-family:system-ui,sans-serif;background:#1c1e26;color:#e8e8f0}
header{padding:12px 16px;border-bottom:1px solid #333}
h1{margin:0 0 8px;font-size:18px}
.hud{display:flex;gap:16px;flex-wrap:wrap;font-size:13px;margin-bottom:10px}
.hud div{background:#262a36;padding:4px 10px;border-radius:6px}
.controls{display:flex;gap:8px;align-items:center}
button{background:#3a6df0;color:#fff;border:0;padding:8px 14px;border-radius:6px;cursor:pointer;font-size:13px}
button:hover{background:#4a7df5}
select{background:#262a36;color:#e8e8f0;border:1px solid #444;padding:8px 10px;border-radius:6px;font-size:13px}
#scene{position:relative;width:640px;height:560px;margin:24px auto;overflow:hidden}
.cube{position:absolute;width:48px;height:48px;cursor:pointer}
.cube .top{position:absolute;inset:0;background:#8a5a2b;transform:skewX(-30deg) scaleY(.5);transform-origin:50% 100%}
.cube .left{position:absolute;left:0;top:24px;width:24px;height:24px;background:#5e3d1c;transform:skewY(30deg);transform-origin:0 0}
.cube .right{position:absolute;right:0;top:24px;width:24px;height:24px;background:#74491f;transform:skewY(-30deg);transform-origin:100% 0}
.cube .label{position:absolute;left:0;top:26px;width:48px;text-align:center;font-size:10px;color:#fff;text-shadow:0 1px 2px #000;pointer-events:none}
.cube.ground .top{background:#3f7d3a}
.cube.ground .left{background:#2c5a29}
.cube.ground .right{background:#356b30}
.cube.stone .top{background:#8a8a92}
.cube.stone .left{background:#5f5f66}
.cube.stone .right{background:#70707a}
.cube.glass .top{background:rgba(150,210,255,.45);border:1px solid #bfe6ff}
.cube.glass .left{background:rgba(120,180,230,.4);border:1px solid #9fd0f5}
.cube.glass .right{background:rgba(135,195,240,.42);border:1px solid #a8d8f8}
.cube.player .top{background:#3a6df0}
.cube.player .left{background:#2749a8}
.cube.player .right{background:#2f57c4}
.cube.player .label{font-weight:700}
.cube.selected .top{outline:2px solid #ffd54a;outline-offset:-2px}
.cube.selected .left{outline:2px solid #ffd54a;outline-offset:-2px}
.cube.selected .right{outline:2px solid #ffd54a;outline-offset:-2px}
.cube:hover{filter:brightness(1.15)}
"}]}
